{"findings":[{"tipo":"GC","causa_raiz":"Concatenação repetida de strings ('s += i.ToString()') e alocação de novos arrays em lote dentro do método Update(). Por serem imutáveis, strings concatenadas em loop geram milhares de objetos descartáveis na Heap a cada frame (mais de 5 MB/frame), forçando ciclos longos e síncronos do Garbage Collector (22.75 ms) que causam travamentos visíveis (stutter).","codigo_refatorado":"using System;
using System.Collections.Generic;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;
        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;
        [Range(1, 50)]
        public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;
        [Range(1, 512)]
        public int cpuScansPerFrame = 1;
        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;
        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private readonly StringBuilder _sharedStringBuilder = new StringBuilder(4096);
        private static readonly List<GameObject> _trackedObjects = new List<GameObject>();
        private MaterialPropertyBlock _propertyBlock;
        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");

        private void Awake()
        {
            _propertyBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                var emptyGo = new GameObject(string.Concat("Empty_", i.ToString()));
                _trackedObjects.Add(emptyGo);
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                var col = quad.GetComponent<Collider>();
                if (col != null) Destroy(col);

                quad.name = string.Concat("Overdraw_", i.ToString());
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                _sharedStringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _sharedStringBuilder.Append(i);
                }
            }

            if (stressCpu)
            {
                for (int k = 0; k < cpuScansPerFrame; k++)
                {
                    int count = _trackedObjects.Count;
                    for (int i = 0; i < count; i++)
                    {
                        var obj = _trackedObjects[i];
                        if (obj != null)
                        {
                            _ = obj.activeInHierarchy;
                        }
                    }
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            _trackedObjects.Add(clone);

            if (useUniqueMaterials)
            {
                var rend = clone.GetComponent<Renderer>();
                if (rend != null)
                {
                    rend.GetPropertyBlock(_propertyBlock);
                    _propertyBlock.SetColor(ColorPropertyId, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value));
                    rend.SetPropertyBlock(_propertyBlock);
                }
            }
        }
    }
}","explicacao_didatica":"Toda vez que juntamos textos com '+' em C#, o jogo não reaproveita o texto antigo; ele cria um texto novinho na memória e descarta o anterior. Fazer isso centenas de vezes a cada frame acumula montanhas de 'lixo'. O Garbage Collector é como um faxineiro que precisa congelar a tela para limpar essa sujeira. Para evitar isso, usamos StringBuilder (que reaproveita a mesma folha em vez de jogar folhas fora) e guardamos objetos em listas em vez de alocar arrays novos o tempo todo."},{"tipo":"CPU","causa_raiz":"Uso repetitivo de 'GameObject.FindObjectsOfType<GameObject>()' dentro do Update. Essa chamada força a Unity a varrer recursivamente todas as entidades da cena ativa e alocar um array com os resultados a cada iteração, gerando gargalo extremo de processamento (picos de 125.67 ms).","codigo_refatorado":"using System.Collections.Generic;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public static class SceneObjectRegistry
    {
        private static readonly List<GameObject> RegisteredObjects = new List<GameObject>(1024);

        public static void Register(GameObject go)
        {
            if (go != null && !RegisteredObjects.Contains(go))
            {
                RegisteredObjects.Add(go);
            }
        }

        public static void Unregister(GameObject go)
        {
            if (go != null)
            {
                RegisteredObjects.Remove(go);
            }
        }

        public static IReadOnlyList<GameObject> AllObjects => RegisteredObjects;
    }
}","explicacao_didatica":"Procurar objetos na cena usando 'FindObjectsOfType' a cada frame é como revirar uma casa inteira do teto ao chão toda vez que você precisa pegar a chave de casa. O correto é guardar a chave sempre no mesmo chaveiro (uma lista ou registro estático). Assim, quando você precisar saber quais objetos existem, basta consultar essa lista instantaneamente sem fazer a CPU procurar em todo lugar."}],"dicas_level_design":null}

